the TE control should handle scrolling automatically, along with insertion oftext, automatically scrolls the text. insertion must be handled quickly -- nomoving of the entire text array with every character. look into backgroundtasks to handle recalculating of line starts, etc. the first characterinserted my be slow; as long as all the rest are fast. For now redraw every-thing after the inserted text. later optimize to only redraw if a line wrapsand to bit-blit text instead of redrawing it. Use offscreen drawing to make it all look smooth. provide special speedups for special cases like: singlefont, fixed-width font, no word wrap, single text rectangle. allow multiplerectangles for the text, but must develop a new way of linking them to handlewrapping. make EVERYTHING into a control; this should be completely automatic.Must decide how to work scroll bars with muliple text rectangles. must figureout some way of getting keystrokes when i'm a control.50 milliseconds maximum per char. so can do 20 chars / sec200 mils at the beginning of a selection100 mils per line of scrolling500 mils per cut, copy, paste25 mils per idle (1/40) second   **********   end of notes on GS TextEdit				 ********** */	print off	INCLUDE  'all.macros'	INCLUDE  'E16.EVENT'	print on	INCLUDE  'GlobalRecords'	INCLUDE  'GlobalVars'	INCLUDE  'MemoryImports'	string asis****************************************************************;;;  super arrays are an array of up to 8192 elements each one of which;  is a handle to up to 8192 elements;;********************************************************************************************************************************setupSuperCache	PROC  ENTRY	PushLong SuperCacheHandle	;get a pointer to the block of items	jsr  DerefHandle	stax SuperLocalPtr	ldy  SuperCacheIndex	;and load the current index	rts	ENDP****************************************************************GetSuperOffset	PROC  EXPORT	lda  SuperCacheHandle	;check to see if the cache handle is zero	ora  SuperCacheHandle+2	;..if it is, there is no cache	beq  notInCache	cmp4 TextOffset,SuperCacheEndOffset	;check the current offset against the	bge  notInCache		;..cache bounds	cmp4 TextOffset,SuperCacheOffset	blt  notInCacheinCache	MoveLong SuperCacheItem,SuperItem	;copy the cached item number	SubLong TextOffset,SuperCacheOffset,SuperOffsetLeft	jsr  setupSuperCache	;setup the local pointer and index	brl  localLoopnotInCache	MoveLong TextOffset,SuperOffsetLeft	;setup the offset counter	stz4 SuperItem		;zero out the super item number	PushLong SuperHandle	;get a pointer to the array of handles	jsr  DerefHandle	stax SuperMainPtrmainLoop	ldy  #2	lda  [SuperMainPtr],y	sta  SuperCacheHandle+2	pha	lda  [SuperMainPtr]	sta  SuperCacheHandle	pha	ora  SuperCacheHandle+2	beq  notFound	jsr  DerefHandle	stax SuperLocalPtr	ldy  #2	lda  [SuperLocalPtr],y	tax	lda  [SuperLocalPtr]	cpx  SuperOffsetLeft+2	blt  skipLocal	bne  doLocal	cmp  SuperOffsetLeft	blt  skipLocal	bne  doLocalskipLocal	ldy  #4	lda  [SuperLocalPtr],y	clc	adc  SuperItem	sta  SuperItem	bcc  @1	inc  SuperItem+2@1	lda  SuperMainPtr	clc	adc  #4	sta  SuperMainPtr	bcc  mainLoop	inc  SuperMainPtr+2	bra  mainLoopdoLocal	clc	adc  TextOffset	sta  SuperCacheEndOffset	txa	adc  TextOffset+2	sta  SuperCacheEndOffset+2	SubLong SuperCacheEndOffset,SuperOffsetLeft,SuperCacheEndOffset	ldy  #4	lda  [SuperLocalPtr],y	clc	adc  SuperItem	sta  SuperCacheEndItem	lda  SuperItem+2	adc  #0	sta  SuperCacheEndItem+2	ldy  #6localLoop	lda  [SuperLocalPtr],y	sta  SuperLength	iny2	lda  [SuperLocalPtr],y	sta  SuperLength+2	cmp4 SuperLength,SuperOffsetLeft	bgt  foundIt	SubLong SuperOffsetLeft,SuperLength,SuperOffsetLeft	inc4 SuperItem	iny4	bra  localLoopfoundIt	tya	dec  A	dec  A	sta  SuperCacheIndex	iny2	lda  [SuperLocalPtr],y	sta  SuperData	SubLong SuperLength,SuperOffsetLeft,SuperLength	SubLong TextOffset,SuperOffsetLeft,SuperCacheOffset	MoveLong SuperItem,SuperCacheItem	clc	rtsnotFound	pla	pla	sec	rts	ENDP****************************************************************GetSuperItem	PROC  EXPORT	lda  SuperCacheHandle	ora  SuperCacheHandle+2	beq  notInCache	cmp4 SuperItem,SuperCacheEndItem	bge  notInCache	cmp4 SuperItem,SuperCacheItem	blt  notInCacheinCache	MoveLong SuperCacheOffset,TextOffset	SubLong SuperItem,SuperCacheItem,SuperItemsLeft	jsr  setupSuperCache	brl  localLoopnotInCache	MoveLong SuperItem,SuperItemsLeft	stz4 TextOffset	PushLong SuperHandle	jsr  DerefHandle	stax SuperMainPtrmainLoop	ldy  #2	lda  [SuperMainPtr],y	sta  SuperCacheHandle+2	pha	lda  [SuperMainPtr]	sta  SuperCacheHandle	pha	ora  SuperCacheHandle+2	beq  notFound	jsr  DerefHandle	stax SuperLocalPtr	ldy  #4	lda  [SuperLocalPtr],y	tax	lda  SuperItemsLeft+2	bne  skipLocal	cpx  SuperItemsLeft	blt  skipLocal	bne  doLocalskipLocal	lda  SuperItemsLeft	sec	sbc  [SuperLocalPtr],y	sta  SuperItemsLeft	lda  SuperItemsLeft+2	sbc  #0	sta  SuperItemsLeft+2	ldy  #2	lda  [SuperLocalPtr]	clc	adc  TextOffset	sta  TextOffset	lda  [SuperLocalPtr],y	adc  TextOffset+2	sta  TextOffset+2	lda  SuperMainPtr	clc	adc  #4	sta  SuperMainPtr	bcc  mainLoop	inc  SuperMainPtr+2	bra  mainLoopdoLocal	txa	clc	adc  SuperItem	sta  SuperCacheEndItem	lda  SuperItem+2	adc  #0	sta  SuperCacheEndItem+2	SubLong SuperCacheEndItem,SuperItemsLeft,SuperCacheEndItem	ldy  #2	lda  [SuperLocalPtr]	adc  TextOffset	sta  SuperCacheEndOffset	lda  [SuperLocalPtr],y	adc  TextOffset+2	sta  SuperCacheEndOffset+2	ldy  #6	lda  SuperItemsLeft	ora  SuperItemsLeft+2	beq  foundItlocalLoop	lda  [SuperLocalPtr],y	sta  SuperLength	clc	adc  TextOffset	sta  TextOffset	iny2	lda  [SuperLocalPtr],y	sta  SuperLength+2	adc  TextOffset+2	sta  TextOffset+2	iny4	dec  SuperItemsLeft	bne  localLoop	foundIt	tya	dec  A	dec  A	sta  SuperCacheIndex	iny2	lda  [SuperLocalPtr],y	sta  SuperData	MoveLong TextOffset,SuperCacheOffset	MoveLong SuperItem,SuperCacheItem	clc	rtsnotFound	pla	pla	sec	rts	ENDP****************************************************************SetSuperItem	PROC  EXPORT	lda  SuperCacheHandle	ora  SuperCacheHandle+2	beq  notInCache	cmp4 SuperItem,SuperCacheEndItem	bge  notInCache	cmp4 SuperItem,SuperCacheItem	blt  notInCacheinCache	SubLong SuperItem,SuperCacheItem,SuperItemsLeft	PushLong SuperCacheHandle	;get a pointer to the block of items	jsr  DerefHandle	clc	adc  SuperCacheIndex	sta  SuperLocalPtr	stx  SuperLocalPtr	bcc  @1	inc  SuperLocalPtr+2@1	brl  doLocalnotInCache	MoveLong SuperItem,SuperItemsLeft	PushLong SuperHandle	jsr  DerefHandle	stax SuperMainPtrmainLoop	ldy  #2	lda  [SuperMainPtr],y	pha	lda  [SuperMainPtr]	pha	ora  3,s	beq  notFound	jsr  DerefHandle	stax SuperLocalPtr	ldy  #4	lda  [SuperLocalPtr],y	tax	lda  SuperItemsLeft+2	bne  skipLocal	cpx  SuperItemsLeft	blt  skipLocal	bne  doLocalskipLocal	lda  SuperItemsLeft	sec	sbc  [SuperLocalPtr],y	sta  SuperItemsLeft	lda  SuperItemsLeft+2	sbc  #0	sta  SuperItemsLeft+2	lda  SuperMainPtr	clc	adc  #4	sta  SuperMainPtr	bcc  mainLoop	inc  SuperMainPtr+2	bra  mainLoopdoLocal	asl  SuperItemsLeft		;multiply the number of items by six	lda  SuperItemsLeft	asl  SuperItemsLeft	clc	adc  SuperItemsLeft	clc	adc  #6		;skip the first 6 bytes in the handle	tay		;use as an index.	lda  SuperLength	sta  [SuperLocalPtr],y	iny	iny	lda  SuperLength+2	sta  [SuperLocalPtr],y	iny	iny	lda  SuperData	sta  [SuperLocalPtr],y	clc	rtsnotFound	pla	pla	sec	rts	ENDP****************************************************************InsertSuperItem	PROC  EXPORT	clc	rts	ENDP****************************************************************RemoveSuperItem	PROC  EXPORTnotInCache	MoveLong SuperItem,SuperItemsLeft	PushLong SuperHandle	jsr  DerefHandle	stax SuperMainPtrmainLoop	ldy  #2	lda  [SuperMainPtr],y	pha	lda  [SuperMainPtr]	pha	ora  3,s	beq  notFound	jsr  DerefHandle	stax SuperLocalPtr	ldy  #4	lda  [SuperLocalPtr],y	tax	lda  SuperItemsLeft+2	bne  skipLocal	cpx  SuperItemsLeft	blt  skipLocal	bne  doLocalskipLocal	lda  SuperItemsLeft	sec	sbc  [SuperLocalPtr],y	sta  SuperItemsLeft	lda  SuperItemsLeft+2	sbc  #0	sta  SuperItemsLeft+2	lda  SuperMainPtr	clc	adc  #4	sta  SuperMainPtr	bcc  mainLoop	inc  SuperMainPtr+2	bra  mainLoopdoLocal	asl  SuperItemsLeft		;multiply the number of items by six	lda  SuperItemsLeft	asl  SuperItemsLeft	clc	adc  SuperItemsLeft	clc	adc  #6		;skip the first 6 bytes in the handle	clc	adc  SuperLocalPtr	sta  SuperLocalPtr	bcc  @1	inc  SuperLocalPtr+2@1	nop	clc	rtsnotFound	pla	pla	sec	rts	ENDP****************************************************************	ENDGetSuperOffset:	uses TextOffset and SuperHandle. searches the super array in SuperHandle for	the item at TextOffset. Sets the SuperItem, SuperLength, and SuperData values.	SuperLength will be the number of characters AFTER TextOffset that the data	pertains to. The SuperCache values will be used if SuperCacheHandle is non zero.	They will also be updated by this routine.GetSuperItem:	uses SuperItem and SuperHandle. Returns the SuperLength, SuperData, and	TextOffset values. The SuperCache values will be used and updated.SetSuperItem:	uses SuperHandle and SuperItem. Sets the length and data fields from SuperLength	and SuperData. The SuperCache values will be used and updated.InsertSuperItem:	uses SuperHandle and SuperItem. Inserts a new item AFTER SuperItem using	the SuperLength and SuperData values. The SuperCache values will be	used and updated.RemoveSuperItem:	uses SuperHandle and SuperItem. The item specified will be removed from the list.	The SuperCache values will be used and updated.****************************************************************OldDoKeystroke	PROC  EXPORT	IMPORT  DoRightDelete	IMPORT  DoLeftArrow	IMPORT  DoDownArrow	IMPORT  DoUpArrow	IMPORT  DoCR	IMPORT  DoRightArrow	IMPORT  DoClear	IMPORT  DoClearEOL	IMPORT  DoDelete	IMPORT  ScrollToSelection	IMPORT  IsSelectionEmpty	IMPORT  GetRecordLong	IMPORT  IsItAWordBreak	IMPORT  SimpleKey	IMPORT  GetSelectionStart	IMPORT  SetRecordLong	IMPORT  AreWeWordWrapping	lda  TheChar	casejmp $06,DoRightDelete	;Ctrl-F	casejmp $08,DoLeftArrow	casejmp $0A,DoDownArrow	casejmp $0B,DoUpArrow	casejmp $0D,DoCR	casejmp $15,DoRightArrow	casejmp $18,DoClear		;ctrl-X, clear	casejmp $19,DoClearEOL	;ctrl-Y	casejmp $7f,DoDelete	;Deletenormalchar	PushWordSpace		;get the width of the character we	PushWord TheChar		;..inserted	_CharWidth	PullWord TheCharWidth	jsr  ScrollToSelection	;scroll to the current selection.	jsr  IsSelectionEmpty	;check to see if we have a selection	bcsl notEmpty	jsr  AreWeWordWrapping	bcsl doSimple		;nope, so do simple case	jsr  GetSelectionStart	;check to see if we are inserting into	ldy  #TERecord.FirstWordEnd	;..the first word	jsr  GetRecordLong	cmpl TextOffset	blt  notInFirst	lda  TheChar		;we are inserting into the first word	jsr  IsItAWordBreak		;..so check for inserting a word break	bcc  notWordBreak	ldax TextOffset		;set the first word end to the	ldy  #TERecord.FirstWordEnd	;..current offset.	jsr  SetRecordLong;	jsr  MeasureTillOffset	;measure from the start of the line to	ldy  #TERecord.FirstWordWidth	;..the current offset. Store the new width	sta  [RecordPtr],y		;..in globals	bra  checkPrevWrapnotWordBreak	ldy  #TERecord.FirstWordEnd	;increment the ending offset for the	jsr  GetRecordLong		;..first word.	incl a	ldy  #TERecord.FirstWordEnd	;increment the ending offset for the	jsr  SetRecordLong		;re-store the value in globals	ldy  #TERecord.FirstWordWidth	;add the width of the inserted character	lda  [RecordPtr],y		;..to the first word width	clc		;..and re-store this in globals	adc  TheCharWidth	sta  [RecordPtr],y	lda  WasSelectionEmpty	;if the selection was empty the width of	cmp  #TRUE		;the first word INCREASED, so we don't	beq  notInFirst		;need to check for wrap to the prev linecheckPrevWrap	ldy  #TERecord.FirstWordWidth	;get the width of the first word into	lda  [RecordPtr],y		;..TempWord	sta  TempWord	ldy  #TERecord.PrevLineLeft	;get the number of pixels left on the	lda  [RecordPtr],y		;..previous line.	cmp  TempWord		;If pixels left >= word width we must	bge  doComplex		;..word wrap, so call doComplexnotInFirst	ldy  #TERecord.LineWidth	;add the width of the character inserted	lda  [RecordPtr],y		;..to the line width and re-store this	clc		;..value in globals	adc  TheCharWidth	sta  TempWord	sta  [RecordPtr],y	ldy  #TERecord.NextFirstWordWidth	;get the width of the first word on the	lda  [RecordPtr],y		;..next line and check to see if it will	clc		;..fit on this line (this is necessary	adc  TempWord		;..there was a non-empty selection)	sta  TempWord+2		;if this word will fit on this line, we	ldy  #TERecord.WrapWidth	;..need to word wrap so call doComplex	lda  [RecordPtr],y	cmp  TempWord+2	bge  doComplex	cmp  TempWord	blt  doComplexdoSimple	jmp  SimpleKeynotEmpty	nop		;do some checks later	brk  $26doComplex	nop	brk  $25	rts	ENDP********************************************************************************************************************************DoCR	PROC  EXPORT	clc	rtsoldHeight	equ  0	jsr  Save0_4	jsr  UnhilightSelection	;hide the old cursor	jsr  ScrollToSelection	;scroll to the current selection.	jsr  IsSelectionEmpty	;check to see if we have a selection	bcsl doComplex	jsr  GetSelectionStart	jsr  FindLineInfo		;get the info for the current line	lda  IsLineEndHard		;is this line ended by a CR or by end	cmp  #FALSE		;..of text ?  If it is not then we need	beql doComplex		;..to word wrap, so go do that.	mov  LineHeight,oldHeight	;save the old line height and ascent.	jsr  InsertChar		;insert the CR into the text.	jsr  GetSelectionStart	incl TextOffset	jsr  SetSelectionStart	jsr  SetSelectionEnd	jsr  AddLineBreak		;add a line break at the current TextOffset.	jsr  GetSelectionStart	decl TextOffset	jsr  FindLineInfo	mov  LineHeight,TextHeight	;the first line new height is in TextHeight	incl TextOffset	jsr  FindLineInfo		;the second line new height is in LineHeight	jsr  GetViewRect	lda  TextVPos		;this is the top of the line rect	clc	adc  oldHeight		;this is the original line height	sta  TempRect.top	lda  LineHeight	clc	adc  TextHeight	sec	sbc  oldHeight	tax	PushZPtr TempRect	PushWord #0	phx	PushLong #0	_ScrollRect	jsr  GetSelectionRect	;erase the rest of this line from the	ldy  #TERecord.ViewRect.right	;..selection on.	jsr  GetRecordWord	sta  TempRect.right	lda  TempRect.top	clc	adc  TextHeight	sta  TempRect.bottom	PushZPtr TempRect	_EraseRect	jsr  GetSelectionStart	jsr  OffsetToPoint	PushWord TextHPos	PushWord TextVPos	_MoveTo	jsr  GetTextFormat		;get the format valuesdrawloop	PushLong TextPtr	PushWord TextCount	_DrawText	lda  TextCount	clc	adc  TextOffset	sta  TextOffset	bcc  @1	inc  TextOffset+2@1	lda  WhatStoppedFormat	cmp  #lineBreak	beq  done	cmp  #endOfText	beq  done	jsr  GetTextFormat	bra  drawloopdone	jsr  HilightSelection	;show the new cursor	jmp  Restore0_4doComplex	brk  $51	ENDP********************************************************************************************************************************* remove all the items from TextOffset to EndOffset****************************************************************RemoveSuperItems	PROC  EXPORT	IMPORT  FindSuperInfo	PushAX		;save the super handle	jsr  FindSuperInfo		;find the right spot in the super array	PushLong TextOffset		;save the starting TextOffset	addl SuperStart,SuperLength,TextOffset	cmpl TextOffset,EndOffset	bgtl nothingToDo	mov  SuperLocalIndex,DestPtr	;save the local index	stzl SuperItemNumber	;use this as a counterremoveLoop	lda  SuperLocalIndex	;move the local index to the next	clc		;..position	adc  #SuperItemSize	sta  SuperLocalIndex	tay	lda  [TempPtr],y		;add the new length to the original	pha		;..length. Also save the new length	clc	adc  SuperLength	sta  SuperLength	iny	iny	lda  [TempPtr],y		;add the high word	tax	adc  SuperLength+2	sta  SuperLength+2	bcsl nextBlock		;if we wrapped around, we are in the	and  SuperLength		;..next block	cmp  #$FFFF		;if $FFFF FFFF then also in the next block	beql nextBlock	iny		;get the new height	iny	lda  [TempPtr],y		;add to the original height	clc	adc  LineHeight	sta  LineHeight	ldy  #BlockRecord.count	;update the line count field	lda  [TempPtr],y	dec  a	sta  [TempPtr],y	incl SuperItemNumber	;increment the number of items we removed	pla		;restore the low word of the new length	clc		;move TextOffset to the next item	adc  TextOffset	sta  TextOffset	txa		;the high word is still in X	adc  TextOffset+2	sta  TextOffset+2	cmp  EndOffset+2	blt  removeLoop	bne  done	lda  TextOffset	cmp  EndOffset	ble  removeLoopdone	ldy  DestPtr		;get our original index	lda  SuperLength		;copy the length into the original line.	sta  [TempPtr],y	iny	iny	lda  SuperLength+2	sta  [TempPtr],y	iny	iny	lda  LineHeight	sta  [TempPtr],y	lda  SuperLocalIndex	clc	adc  #SuperItemSize	sta  MoveLength	adc  TempPtr	sta  SourcePtr	lda  TempPtr+2	adc  #0	sta  SourcePtr+2	lda  DestPtr	adc  #SuperItemSize		;carry is already clear	sta  SuperLocalIndex	adc  TempPtr	sta  DestPtr	lda  TempPtr+2	adc  #0	sta  DestPtr+2	ldy  SuperMainIndex		;get the local handle into TempPtr	lda  [MainSuperPtr],y	tax	iny	iny	lda  [MainSuperPtr],y	pha		;one copy for set handle size	phx	pha		;..and one for get handle size	phx	jsr  GetHandleSize	pha		;save the size (one word)	sec	sbc  MoveLength	sta  MoveLength	stz  MoveLength+2	jsr  BlockMove	pla	clc	adc  DestPtr	