t* destroys TempPtr, TempWord, & TempLong****************************************************************RemoveLineStarts	PROC  EXPORTItemsRemoved	equ  SuperItemNumberMaxLength	equ  EndOffset	jsr  GetLineSuperHandle	;find the starting line in the super	jsr  FindSuperInfo		;array.	lda  SuperStart		;do a quick check to see if we are	clc		;..removing items or not. If not then	adc  SuperLength		;..quickly exit.	tax	lda  SuperStart+2	adc  SuperLength+2	cmp  EndOffset+2	blt  mustRemoveItems	cpx  EndOffset	bgtl nothingToDomustRemoveItems	ldy  SuperMainIndex		;save the original local handle	lda  [MainSuperPtr],y	sta  SuperLocalHandle	iny	iny	lda  [MainSuperPtr],y	sta  SuperLocalHandle+2	subl EndOffset,SuperStart,MaxLength	;we stop when SuperLength reaches MaxLength	stzl ItemsRemoved		;use this as an item counter	stzl SuperLength		;zero out SuperLength for the loop and	stz  LineHeight		;..the same with line height	ldy  SuperLocalIndex	;start at the current indexitemStart	sty  DestPtr		;save the starting indexitemLoop	lda  [TempPtr],y		;get the length of the current item	sta  TempWord		;save it temporarily	clc		;X, A will contain the old super length	adc  SuperLength		;..plus the length of the new item	tax		;..X is low, A is High	iny	iny	lda  [TempPtr],y		;but first check to see if we are at	and  TempWord		;..the end of a block ($FFFF FFFF)	cmp  #$FFFF	beql nextBlock		;yes, goto next block	lda  [TempPtr],y		;add the high word of the lengths and	clc		;..compare against the maximum length	adc  SuperLength+2	cmp  MaxLength+2	blt  itemContinue	bne  removeItems	cpx  MaxLength	bge  removeItemsitemContinue	stx  SuperLength+2		;store the new length	sta  SuperLength	iny	iny	tya	clc	adc  #SuperItemSize-4	pha		;save on the stack	incl ItemsRemoved	ldy  #SuperBlockRecord.count	;fix the block count field.	lda  [TempPtr],y	dec  a	sta  [TempPtr],y	ply		;restore our index	bra  itemLoopremoveItems	bne  skipLastItem		;check 