*********************************CalculateLineHeight	PROC  EXPORT	PushZLong EndOffset		;save the original ending offset	PushZLong TextOffset	;save the original text offset	jsr  FindLineInfo	stz  LineHeight	stz  LineAscent	lda  SuperStart	sta  TextOffset	clc	adc  SuperLength	sta  EndOffset	lda  SuperStart+2	sta  TextOffset+2	adc  SuperLength+2	sta  EndOffset+2heightLoop	jsr  FindStyleInfo		;find the new style information	lda  SuperData		;see, if there is a new style item	cmp  TextStyleItem	beq  skipSetStyle		;nope = skip this	sta  TextStyleItem		;yes, so setup the values	jsr  InstallStyleItemskipSetStyle	lda  TextHeight	cmp  LineHeight	blt  @1	sta  LineHeight@1	lda  TextAscent	cmp  LineAscent	blt  @2	sta  LineAscent@2	addl SuperStart,SuperLength,TextOffset	cmpl TextOffset,EndOffset	blt  heightLoop	mov  LineHeight,SuperData	mov  LineAscent,SuperData+2	jsr  GetLineSuperHandle	jsr  SetSuperData	PullLong TextOffset		;restore the original text offset	PullLong EndOffset		;restore the original ending offset	rts	ENDP***************************************************************** This routine takes TextOffset as an input. TextOffset is an offset* to the first line that changed. This line and all subsequent lines* must be reformatted. This routine will also redraw the lines that* it needs to. It will also scroll lines, by keeping track* of the old TextVPos and the new TextVPos.****************************************************************RewrapLines	PROC  EXPORTaddFlag	equ  0oldHeight	equ  2	jsr  Save0_4	stz  addFlag		;this is for scrolling adjustment	ldy  #TERecord.TextLength	;if there is no text, we can skip this	jsr  GetRecordLong		;..entire routine - (there are no lines)	stx  TempWord	ora  TempWord	beql justRedraw	jsr  AreWeWordWrapping	bcc  simple		;nopecomplex	brk  $4A		;needs more work.simple	PushZLong TextOffset	;save the starting text offset	jsr  FindLineInfo		;move the offset to the beginning of the	movl SuperStart,TextOffset	;..current line	mov  LineHeight,oldHeight	jsr  OffsetToPoint		;find the TextVPos	lda  TextVPos	clc	adc  LineHeight	sta  OldNextVPos		;this is the old VPos of the next lineblockLoopStart	stzl SuperLength		;zero out the length fieldblockLoop	jsr  FindBlockInfo		;get the text pointer	jsr  BlockToTextPtr	lda  BlockCount		;are we done ?	beql thruWrapping	ldy  #0		;search for a CR.	shortmfindCRLoop	lda  [TextPtr],y	cmp  #$0D	beq  foundCR	iny	cpy  BlockCount	blt  findCRLoop	longm	tya		;move the text offset forward by block	clc		;..count	adc  TextOffset		;(Y is the block count)	sta  TextOffset	bcc  @1	inc  TextOffset+2@1	tya		;add block count to the new line length	clc		;(Y is the block count)	adc  SuperLength	sta  SuperLength	bcc  @2	inc  SuperLength+2@2	ldy  #TERecord.TextLength	;are we at the end of the text ?	jsr  GetRecordLong		;..nope so go back to the block loop	cmp  TextOffset	bne  blockLoop	cpx  TextOffset+2	bne  blockLoop	brl  checkLine		;we are done if we are at the endfoundCR	longm		;back to long mode	tya		;where were we at ?	sec		;skip over the CR	adc  TextOffset		;move the text offset to the new spot.	sta  TextOffset	bcc  @1	inc  TextOffset+2@1	tya		;add to the length.	sec	adc  SuperLength	sta  SuperLength	bcc  checkLine	inc  SuperLength+2checkLine	jsr  GetLineSuperHandle	;get the line super pointers -- note	jsr  SetupSuperPtrs		;..we must already be at the right spot	lda  [TempPtr],y		;is the new length != the old length ?	cmp  SuperLength		;then, we need to add a new item	bne  addItem	iny	iny	lda  [TempPtr],y	cmp  SuperLength+2	beq  checkForThru		;exactly equal means we are done.addItem	lda  #$FFFF	sta  addFlag	jsr  GetLineSuperHandle	jsr  InsertSuperItem	;insert a line at the current offset	ldy  #TERecord.NumberOfLines	;increment the number of lines	jsr  IncRecordLong	decl TextOffset		;move to the previous line	jsr  CalculateLineHeight	;get the height	lda  TextVPos		;move the new top of line down by the	clc		;..height of the previous line	adc  LineHeight	sta  TextVPos	incl TextOffset		;move to the new line	jsr  CalculateLineHeight	;get the new height	brl  blockLoopStart		;go back for another linecheckForThru	ldy  #TERecord.TextLength	;are we at the very end ?	jsr  GetRecordLong	cmpl TextOffset	bne  thruWrapping	decl TextOffset	jsr  FindBlockInfo	jsr  BlockToTextPtr	incl TextOffset	lda  [TextPtr]		;was the last character a CR ?	and  #$00FF	cmp  #$0D	bne  thruWrapping		;..nope	jsr  FindLineInfo		;we are, so find the line info	cmpl SuperStart,TextOffset	;if there is alreay a new line, then	bne  addItem		;..quit. otherwise, add the linethruWrapping	decl TextOffset	jsr  CalculateLineHeight	;recal the line height for this line	incl TextOffset	jsr  GetViewRect		;setup the scrolling rectangle	lda  OldNextVPos		;start at the old next position	ldx  addFlag	bne  skipAdjust	sec	sbc  oldHeight	clc	adc  LineHeightskipAdjust	sta  TempRect.top	lda  TextVPos		;get the new top position of the line	clc		;..that didn't change	adc  LineHeight	sta  TextVPos	sec	sbc  OldNextVPos	sta  OldNextVPos		;save the amount to scroll	beq  skipScroll	PushZPtr TempRect	PushWord #0	PushZWord OldNextVPos	PushLong #0	_ScrollRect	lda  OldNextVPos	bpl  skipScroll; must redraw the bottom hereskipScroll	movl TextOffset,SavedOffset	lda  1,s	sta  TextOffset	lda  3,s	sta  TextOffset+2drawLoop	jsr  RedrawLine	cmpl TextOffset,SavedOffset	blt  drawLoop	PullLong TextOffset		;restore text offsetallDone	jmp  Restore0_4justRedraw	jsr  RedrawLine	bra  allDone	ENDP****************************************************************	INCLUDE  'GlobalIncludes'****************************************************************DebugPrintMain	PROC  EXPORT	phb	phk	plb	jsr  SetupDebugPrint	PushWord #10	PushWord #20	_MoveTo	PushWord Value1	PushLong #tempStr	PushWord #5	PushWord #1	_Int2Dec	PushLong #tempStr	_DrawCString	PushWord #110	PushWord #20	_MoveTo	PushWord Value2	PushLong #tempStr	PushWord #5	PushWord #1	_Int2Dec	PushLong #tempStr	_DrawCString	PushWord #210	PushWord #20	_MoveTo	PushWord Value3	PushLong #tempStr	PushWord #5	PushWord #1	_Int2Dec	PushLong #tempStr	_DrawCString	PushWord #310	PushWord #20	_MoveTo	PushWord Value4	PushLong #tempStr	PushWord #5	PushWord #1	_Int2Dec	PushLong #tempStr	_DrawCString	jsr  RestoreDebugPrint	plb	rts	EXPORT Value1,Value2,Value3,Value4Value1	ds.w  1Value2	ds.w  1Value3	ds.w  1Value4	ds.w  1tempStr	ds.b  5	dc.b  ' ',0	ENDP****************************************************************DebugPrintDefProc	PROC  EXPORT	DefineStack		;these are our direct page variablesOrigB	byte		;..for the defprocOrigD	wordRTL	block 3theControlHandle	longctrlParam	longctrlMessage	wordresult	long	phb	phk	plb	jsr  SetupDebugPrint	inc  debugCount	PushWord #100	PushWord #10	_MoveTo	PushLong #mess1	_DrawCString	lda  ctrlMessage	jsr  DrawHexWord	PushLong #mess2	_DrawCString	ldax ctrlParam	jsr  DrawHexLong	PushLong #mess3	_DrawCString	ldax theControlHandle	jsr  DrawHexLong	PushLong #mess4	_DrawCString	PushWord debugCount	PushLong #tempStr	PushWord #4	PushWord #0		;not signed	_Int2Dec	PushLong #tempStr	_DrawCString	lda  ctrlMessage	cmp  #0	bra  doneloop	PushWordSpace                    ;pause for a key	PushWord #$000A	PushLong #extraRecord	_GetNextEvent	pla	beq  loopdone	jsr  RestoreDebugPrint	plb	rtsmess1	dc.b  'Message = $',0mess2	dc.b  ', Parameter = $',0mess3	dc.b  ', Handle = $',0mess4	dc.b  ',  ',0extraRecord	ds.b  32debugCount	dc.w  0tempStr	ds.b  4	dc.b  0	ENDP****************************************************************SetupDebugPrint	PROC  EXPORT	EXPORT  SetDebugPort	EXPORT  RestoreDebugPrint;---------------------------------------------------------------	PullWord returnAddr	PushLongSpace		;save the old port	_GetPort	PushLong DebugPort	_SetPort	PushLongSpace	_GetVisHandle		;leave it on the stack	PushLongSpace	_NewRgn	lda  3,s	tax	lda  1,s	PushAX		;save three total copies on the stack	PushAX	PushWord #-2000	PushWord #-2000	PushWord #2000	PushWord #2000	_SetRectRgn		;use first copy	_SetVisHandle		;use second copy	PushLong #clearRect	_EraseRect	PushWord returnAddr	rts;---------------------------------------------------------------SetDebugPort	phb	phk	plb	stax DebugPort	plb	rts;---------------------------------------------------------------RestoreDebugPrint	PullWord returnAddr	_DisposeRgn		;dispose our clipping region	_SetVisHandle	_SetPort		;restore the port	PushWord returnAddr	rts;---------------------------------------------------------------returnAddr	ds.w  1clearRect	dc.w  0,0,28,640DebugPort	ds.l  1	ENDP***************************************************************** the value to be draw comes in in A****************************************************************DrawHexWord	PROC  EXPORT	phb		;save the data bank	phk		;set it to ours	plb	PushLongSpace	pha	_HexIt	PullLong tempStr	PushLong #tempStr	_DrawCString	plb		;restore the data bank	rtstempStr	ds.b  4	dc.b  0	ENDP***************************************************************** the value to be draw comes in in A and X****************************************************************DrawHexLong	PROC  EXPORT	phb		;save the data bank	phk		;set it to ours	plb	PushLongSpace		;save low word for later	pha	PushLongSpace		;do high word first.	phx	_HexIt	PullLong tempStr	PushLong #tempStr	_DrawCString	_HexIt		;now do the low word	PullLong tempStr	PushLong #tempStr	_DrawCString	plb		;restore the data bank	rtstempStr	ds.b  4	dc.b  0	ENDP********************************************************************************************************************************* This routine takes TextOffset as an input and returns the* top of the line in TextVPos and the left of the character in* TextHPos****************************************************************OffsetToPoint	PROC  EXPORToriginalOffset	equ  0myCounter	equ  0	jsr  Save0_4		;get space for our locals	movl TextOffset,originalOffset	;save this for later	ldy  #TERecord.ViewRect.top	jsr  GetRecordLong		;this gets both the top and left	sta  TextVPos		;this is the top	stx  TextHPos		;this is the left	ldy  #TERecord.VertScrollPos	;this is the offset for the top of the	jsr  GetRecordLong		;..screen.	stax TextOffsetlineLoop	jsr  FindLineInfo		;get information on the line	lda  TextOffset	clc	adc  SuperLength	tax		;save in X	sta  TextOffset	lda  TextOffset+2	adc  SuperLength+2	sta  TextOffset+2	cmp  originalOffset+2	blt  keepGoing	bne  foundLine	cpx  originalOffset	blt  keepGoing	bne  foundLinecheckEnd	ldy  #TERecord.NumberOfLines+2	lda  [RecordPtr],y	cmp  LineNumber+2	bne  keepGoing	dey	dey	lda  [RecordPtr],y	cmp  LineNumber	beq  foundLinekeepGoing	lda  TextVPos		;add the line height to TextVPos	clc	adc  LineHeight	sta  TextVPos	bra  lineLoopfoundLine	movl SuperStart,TextOffset	;start at the beginning of this line	lda  originalOffset	sec	sbc  TextOffset	sta  myCounter	lda  originalOffset+2	sbc  TextOffset+2	sta  myCounter+2	jsr  GetLeftMargin		;later on, we need to test for stuff	clc		;..like left just, etc	adc  TextHPos	sta  TextHPos	jsr  SetupWidthTable	;setup the width table pointermainLoop	jsr  GetTextFormat	lda  myCounter+2	bne  skipCheck	lda  myCounter	beq  done	cmp  TextCount	bge  skipCheck	sta  TextCountskipCheck	lda  myCounter	sec	sbc  TextCount	sta  myCounter	bcs  @1	dec  myCounter+2@1	lda  #0	shortm	ldx  TextCount	bra  loopEndwidthLoop	txy	lda  [TextPtr],y	tay	lda  [WidthTablePtr],y	clc	adc  TextHPos	sta  TextHPos	bcc  loopEnd	inc  TextHPos+1loopEnd	dex	bne  widthLoop	lda  [TextPtr]		;do the last one.	tay	lda  [WidthTablePtr],y	longm		;back to long mode here	clc	adc  TextHPos	sta  TextHPos	lda  TextOffset	clc	adc  TextCount	sta  TextOffset	bcc  @2	inc  TextOffset+2@2	lda  myCounter	ora  myCounter+2	bne  mainLoopdone	jsr  FreeWidthTable		;unlock the width table	jmp  Restore0_4	ENDP***************************************************************** This routine takes TextOffset as an input. It draws the line* from TextOffset to the end if it is left justified; otherwise* it draws the entire line.****************************************************************RedrawLine	PROC  EXPORT	jsr  FindLineInfo	jsr  GetJust		;get the current justification	cmp  #leftJust	beq  doLeft	movl SuperStart,TextOffset	jsr  OffsetToPoint	jsr  MeasureLineWidth	sta  TextHPos	jsr  GetLeftEdge	pha	jsr  GetRightMargin	sec	sbc  1,s	plx;	sta  WrapWidthdoLeft	lda  TextHPos		;position the cursor for drawing	sta  TempRect.left	pha	lda  TextVPos	sta  TempRect.top	clc	adc  LineAscent	pha	_MoveTodrawloop	jsr  GetTextFormat		;get the format values	ldy  #o_PnLoc+2		;get the horizontal pen position before	lda  [GrafPortPtr],y	;..the draw operation	sta  TempRect.left	PushZLong TextPtr	PushZWord TextCount	_DrawText	lda  TextCount	clc	adc  TextOffset	sta  TextOffset	bcc  @1	inc  TextOffset+2@1	lda  WhatStoppedFormat	cmp  #lineBreak	beq  done	cmp  #endOfText	beq  done	cmp  #styleBreak		;if not style break then loop back	bne  drawloop	lda  LineAscent	sec	sbc  TextAscent	beq  drawLoop	clc	adc  TextVPos	sta  TempRect.bottom	ldy  #o_PnLoc+2		;horizontal pen position	lda  [GrafPortPtr],y	sta  TempRect.right	jsr  EraseTempRect	bra  drawloopdone	ldy  #o_PnLoc+2		;horizontal pen position	lda  [GrafPortPtr],y	;erase the rest of the line	sta  TempRect.left	lda  TempRect.top	clc	adc  LineHeight	sta  TempRect.bottom	ldy  #TERecord.ViewRect.right	lda  [RecordPtr],y	sta  TempRect.right	jsr  EraseTempRect	clc	rts	ENDP****************************************************************DoDelete	PROC  EXPORT	jsr  UnhilightSelection	;remove the selection from the screen	jsr  GetSelectionStart	;where are we ?	lda  TextOffset	ora  TextOffset+2	beql allDone	decl TextOffset		;move back one character	jsr  SetSelectionStart	;set the new cursor offset.	jsr  SetSelectionEnd	ldax TextOffset;	jsr  DeleteChar		;remove this character from the block;	lda  TextOffset		;we need to find some way to fix;	ora  TextOffset+2		;..this bug without kludges;	beq  skip;	decl TextOffsetskip;	jsr  RewrapLines	jsr  GetSelectionStart	;set the new cursor position.	jsr  OffsetToPoint	jsr  PointToCaretallDone	jsr  HilightSelection	clc	rts	ENDP****************************************************************InsertChar	PROC  EXPORT	jsr  GetSelectionStart	;get the selection start into TextOffset	jsr  FindBlockInfo		;get block info for the current selection	subl TextOffset,BlockStart,SourcePtr	;the number of chars before the insert	subl BlockLength,SourcePtr,MoveLength	;calculate the number of chars to move	incl BlockLength		;increment the block length and re-store	jsr  SetBlockSize		;..it in the block list	ldy  #2		;add the start of the block to source ptr	lda  [BlockHandle]	clc	adc  SourcePtr	sta  SourcePtr	lda  [BlockHandle],y	adc  SourcePtr+2	sta  SourcePtr+2	ldax SourcePtr		;copy source ptr to dest ptr. dest will be	inc  a		;..one greater than source, so as to make	bne  @1		;..space for one character.	inx@1	stax DestPtr	jsr  BlockMove	shortm	lda  TheChar		;store the character in the text	sta  [SourcePtr]	longm	ldy  #TERecord.TextLength	;increment the text length	jsr  IncRecordLong	jsr  FindLineInfo		;bump the line length counter by one	incl SuperLength	jsr  SetLineLength	ldy  #TERecord.monoStyle	lda  [RecordPtr],y	cmp  #TRUE	beq  skipStyle	jsr  FindStyleInfo		;bump the style length counter by one	incl SuperLength	jsr  SetStyleInfo		;..since we didn't add any lines.skipStyle	clc	rts	ENDP****************************************************************DeleteChar	PROC  EXPORT	jsr  GetSelectionStart	;get the selection start into TextOffset	jsr  FindBlockInfo		;get block info for the current selection	subl TextOffset,BlockStart,DestPtr	;the number of chars before the delete	subl BlockLength,DestPtr,MoveLength	;calculate the number of chars to move	decl MoveLength	ldy  #2		;add the start of the block to source ptr	lda  [BlockHandle]	clc	adc  DestPtr	sta  DestPtr	lda  [BlockHandle],y	adc  DestPtr+2	sta  DestPtr+2	ldax DestPtr		;copy source ptr to dest ptr. dest will be	inc  a		;..one greater than source, so as to make	bne  @1		;..space for one character.	inx@1	stax SourcePtr	jsr  BlockMove	decl BlockLength		;decrement the block length and re-store	jsr  SetBlockSize		;..it in the block list	ldy  #TERecord.TextLength	lda  [RecordPtr],y	dec  a	sta  [RecordPtr],y	cmp  #$FFFF	bne  @2	iny	iny	lda  [RecordPtr],y	dec  a	sta  [RecordPtr],y@2	jsr  FindLineInfo		;bump the line length counter by one	decl SuperLength	jsr  SetLineLength	ldy  #TERecord.monoStyle	lda  [RecordPtr],y	cmp  #TRUE	beq  skipStyle	jsr  FindStyleInfo		;bump the style length counter by one	decl SuperLength	jsr  SetStyleInfoskipStyle	clc	rts	ENDP****************************************************************	END;---------------------------------------------------------------; Quickdraw equates...stolen directly from the qd.equate file. Maybe later; use QD's actual file.;---------------------------------------------------------------	DSECT $00o_PortSCB	wordo_ImageRef	longo_Width	wordo_BoundsRect	block 8o_PortRect	block 8o_ClipRgn	long		;start of the stuff that we saveo_VisRgn	longo_BkPat	block 32o_PnLoc	longo_PnSize	longo_PnMode	wordo_PnPat	block 32o_PnMask	block 8o_PnVis	wordo_Font	longo_FontID	longo_FontFlags	wordo_TxSize	wordo_TxFace	wordo_TxMode	wordo_SpExtra	longo_ChExtra	longo_FGColor	wordo_BGColor	word		;end of the stuff that we saveo_PicSave	longo_RgnSave	longo_PolySave	longo_GrafProcs	longo_ArcRot	wordo_UserField	longo_SysField	long;---------------------------------------------------------------	PushLongSpace		;space for control handle	PushZLong GrafPortPtr	;push the current port's pointer	ldax ParameterPtr		;pointer to the bounding rectangle	clc	adc  #TEParam.viewRect	bcc  @1	inx@1	PushAX	PushLong #0		;CtlData field	PushWord #0		;CtlFlags field	PushWord #0		;CtlValue	PushLong #0		;Param1 + Param2	PushLong #TEDefProc		;my custom defproc	PushLong #0		;refcon.. for application use	PushLong #0		;color table pointer	_NewControl		;get our text edit control***************************************************************** This routine takes a pointer to the new ruler block in A,X****************************************************************AddToRulerList	PROC  EXPORT	stax MemoryPtr		;save the pointer to the new ruler	ldx  #MinRulerSize		;calculate the ruler size	ldy  #TERuler.tabType	lda  [MemoryPtr],y	cmp  #noTabs	beq  resizeIt	inx		;if equal tabs then the ruler is two bytes	inx		;..bigger	cmp  #equalTabs	beq  resizeIt	inx		;if user tabs then the ruler is four bytes	inx		;..bigger than the minimum	cmp  #variableTabs	bne  resizeIt	ldy  #TERuler.numberOfTabs	;the ruler has a variable number of tabs	lda  [MemoryPtr],y		;..so find out how many, multiply by four	asl  a		;..add the minimum size, and add two for	asl  a		;..the count to get the final ruler size.	clc	adc  #MinRulerSize+2	taxresizeIt	stx  RulerSize	ldy  #TERecord.RulerList	;the new ruler is not in the list, so	jsr  GetRecordLong		;..add it to the end of the list	PushAX		;three copys of the list handle for	PushAX		;..Get, Set, and Deref.	PushAX	jsr  GetHandleSize	stax TextRulerOffset	clc	adc  RulerSize	bcc  @1	inx@1	jsr  SetHandleSize	lda  TextRulerOffset	sec	sbc  #4	sta  TextRulerOffset	bcs  @2	dec  TextRulerOffset+2@2	jsr  DerefHandle		;get a pointer to the end of the new list.	clc	adc  TextRulerOffset	sta  TempPtr	txa	adc  TextRulerOffset+2	sta  TempPtr+2	ldy  #2		;set the new count field to one.	lda  #1	sta  [TempPtr]	dec  a	sta  [TempPtr],y	ldy  #4		;then copy in the new ruler@loop	lda  [MemoryPtr],y	sta  [TempPtr],y	iny	iny	cpy  RulerSize	blt  @loop	jmp  TerminateTempPtr	ENDP********************************************************************************************************************************InitialWordWrapOld	PROC  EXPORTNewLineLength	equ  $00	PushZLong NewLineLength	PushLong [RecordPtr],TERecord.LineSuper	jsr  KillSuperHandle	ldy  #TERecord.NumberOfLines	;clear the number of lines field	lda  #0	tax	jsr  SetRecordLong	ldy  #TERecord.TextLength	;if there is no text, we can skip this	jsr  GetRecordLong		;..entire routine - (there are no lines)	stx  TempWord	ora  TempWord	bne  wordWrap	PullLong NewLineLength	rts		;return right here, if there is no text.;---------------------------------------------------------------wordWrap	stzl TextOffset		;start at the beginning of the text and	lda  #LineSuperItemSize*256+MinSuperBlockSize	jsr  GetSmallHandle		;get a handle for the new line starts	stax LineBlockHandle	;..array	PushAX		;lock it down and get two pointers:	jsr  LockHandle		;..one to the start and one to the current	stax LineBlockStart		;..item	clc	adc  #SuperBlockRecord.firstItem	bcc  @1	inx@1	stax LineStartsPtr	ldy  #TERecord.TextLength	;set the initial length field of the super	jsr  GetRecordLong		;..block	stax [LineBlockStart],SuperBlockRecord.length	ldy  #SuperBlockRecord.count	;clear the initial count field of the	lda  #0		;..super block	sta  [LineBlockStart],y	stz  LineStartsCount	;zero out the count field.	jsr  SetupWidthTable	;setup the width table pointer;---------------------------------------------------------------lineLoop	stz  NewLineLength	stz  LineHeight	stz  LineAscent	jsr  GetWrapWidth		;get the width of the line.	sta  WrapWidth	sta  LineWidth;---------------------------------------------------------------mainLoop	jsr  FindStyleInfo		;find the new style information	bcc  @1	jsr  InstallStyleItem@1	jsr  GetSuperCount	sta  TextCount	jsr  FindBlockInfo		;find the current block information	jsr  BlockToTextPtr	lda  BlockCount	cmp  TextCount	bge  @2	sta  TextCount@2	lda  TextHeight		;set the height and ascent fields	cmp  LineHeight	blt  @skipHeight	sta  LineHeight@skipHeight	lda  TextAscent	cmp  LineAscent	blt  @skipAscent	sta  LineAscent@skipAscent	lda  #0		;zero out both A and X	tax	shortm		;short mode for speed;---------------------------------------------------------------widthLoop	txy	lda  [TextPtr],y		;get the character	cmp  #$0D		;is it a carriage return ?	beq  foundCR	cmp  #TAB	beq  doTab	tay		;use as an index into the width table	lda  WrapWidth		;subtract the character width	sec	sbc  [WidthTablePtr],y	sta  WrapWidth	bcs  @1	dec  WrapWidth+1	bmi  breakIt		;did we go below zero ?@1	inx		;increment our counter	cpx  TextCount	blt  widthLoop		;branch back;---------------------------------------------------------------	longm		;we need a new block of text, here	ldx  TextCount		;add TextCount to the new line's length	jsr  addXToTextOffset	ldy  #TERecord.TextLength	;check for being at the end of the text.	jsr  GetRecordLong	cmp  TextOffset	bne  mainLoop	cpx  TextOffset+2	bne  mainLoop	brl  lastBreak;---------------------------------------------------------------doTab	longm	brk  $4B;---------------------------------------------------------------foundCR	longm	inx		;skip over the CR	jsr  addXToTextOffset	jsr  forceBreak	brl  lineLoop;---------------------------------------------------------------breakIt	lda  [WidthTablePtr],y	;get the width of the current char	longm		;back to long mode (B = 0)	clc		;add it back to the WrapWidth	adc  WrapWidth	sta  WrapWidth	sta  LineWidth	jsr  addXToTextOffset	tya		;the character was in the Y-Reg	jsr  IsItNotAWordBreak	;is the character a word break ?	bcc  skipOverThem		;if yes, then skip over them	lda  TextOffset		;move back to the beginning of this line	sec	sbc  NewLineLength	sta  TextOffset	bcs  @1	dec  TextOffset+2@1	jsr  FindTextPtr	ldx  NewLineLength;---------------------------------------------------------------@loop	dex	bmi  breakAtEnd	txy	lda  [TextPtr],y	and  #$00FF	tay	lda  [WidthTablePtr],y	and  #$00FF	clc	adc  WrapWidth	sta  WrapWidth	tya	jsr  IsItNotAWordBreak	bcs  @loop;---------------------------------------------------------------	lda  [WidthTablePtr],y	;subtract the width of the character	and  #$00FF	sta  TempWord	lda  WrapWidth	sec	sbc  TempWord	sta  WrapWidth	inx	stx  NewLineLength	txaaddIt	addl TextOffset	jsr  forceBreak	brl  lineLoopbreakAtEnd	mov  LineWidth,WrapWidth	lda  NewLineLength	bra  addIt	;---------------------------------------------------------------skipOverThem	inc  NewLineLength	incl TextOffset	ldy  #TERecord.TextLength	lda  [RecordPtr],y	cmp  TextOffset	bne  @ok	iny	iny	lda  [RecordPtr],y	cmp  TextOffset+2		;if at the end, then break.	beq  lastBreak@ok	jsr  FindTextPtr	lda  #0	shortm	lda  [TextPtr]	tay	lda  WrapWidth	sec	sbc  [WidthTablePtr],y	sta  WrapWidth	bcs  @1	dec  WrapWidth+1@1	longm	tya	jsr  IsItNotAWordBreak	bcc  skipOverThem	jsr  forceBreak	brl  lineLoop;---------------------------------------------------------------lastBreak	jsr  forceBreak		;break at the very end of the text.	jsr  FreeWidthTable	ldy  #TERecord.NumberOfLines	jsr  GetRecordLong	clc	adc  LineStartsCount	bcc  @1	inx@1	ldy  #TERecord.NumberOfLines	jsr  SetRecordLong	ldy  #2	lda  #$FFFF	sta  [LineStartsPtr]	sta  [LineStartsPtr],y  IF LineSuperItemSize<>8 THEN      AERROR 'WARNING... The multiply code must change !'  ENDIF	ldax LineBlockHandle	PushAX		;for the set handle size	PushAX		;for the get handle size	PushAX		;for the unlock	jsr  UnlockHandle	lda  #256	sec	sbc  LineStartsCount	asl  a	asl  a	asl  a	sta  LineStartsCount	jsr  GetHandleSize	sec	sbc  LineStartsCount	bcs  @2	dex@2	jsr  SetHandleSize;---------------------------------------------------------------	lda  #MinSuperSize	jsr  GetClearHandle	PushAX		;for the unlock	PushAX		;for the lock	stax [RecordPtr],TERecord.LineSuper	jsr  LockHandle	stax TempPtr	ldy  #SuperRecord.terminator	jsr  TerminateTempPtr	ldy  #SuperRecord.mainIndex	lda  #SuperRecord.firstItem	;set the main index cache value	sta  [TempPtr],y	iny	iny	lda  #SuperBlockRecord.firstItem	;set the local index cahce value	sta  [TempPtr],y	ldy  #SuperRecord.itemNumber	;set the low word of item # to one	lda  #1	sta  [TempPtr],y	ldy  #SuperRecord.itemSize	;set the item size field	lda  #LineSuperItemSize	sta  [TempPtr],y	jsr  UnlockHandle		;unlock the main handle from the stack;---------------------------------------------------------------	ldy  #SuperRecord.firstItem	lda  LineBlockHandle	sta  [TempPtr],y	iny	iny	lda  LineBlockHandle+2	sta  [TempPtr],y;---------------------------------------------------------------	ldy  #TERecord.VertScrollBar	jsr  GetRecordLong	stx  TempWord	ora  TempWord	beq  @skipParams	ldy  #TERecord.NumberOfLines	;this won't work for more than 64K lines	lda  [RecordPtr],y	pha	jsr  CountLinesInView	;returns the number of lines in the view	pha		;..rect	ldy  #TERecord.VertScrollBar	jsr  GetRecordLong	PushAX	stax TempPtr	_SetCtlParams 	jsr  DerefTempPtr	ldy  #CtrlRecord.ctlRect@loop	lda  [TempPtr],y	tyx	sta  TempRect-CtrlRecord.ctlRect,x	iny	iny	cpy  #CtrlRecord.ctlRect+8	blt  @loop	PushZPtr TempRect	_InvalRect@skipParams	stzl TextOffset	PullLong NewLineLength	rts;---------------------------------------------------------------;---------------------------------------------------------------; this subroutine puts a line break in at the current NewLineLength;---------------------------------------------------------------forceBreak	ldy  #2	lda  NewLineLength		;set the new line length	sta  [LineStartsPtr]	lda  #0	sta  [LineStartsPtr],y	iny	iny	lda  LineHeight		;set the new line height	sta  [LineStartsPtr],y	iny	iny	lda  LineAscent		;set the new line ascent	sta  [LineStartsPtr],y	iny	iny	lda  #LineSuperItemSize	addl LineStartsPtr	ldy  #SuperBlockRecord.count	lda  [LineBlockStart],y	inc  a	sta  [LineBlockStart],y	inc  LineStartsCount	;increment our count	lda  LineStartsCount	cmp  #256	bne  @done	ldax LineBlockHandle	PushAX		;for the lock	PushAX		;for the set handle size	PushAX		;for the get handle size	PushAX		;for the unlock	jsr  UnlockHandle	jsr  GetHandleSize	stax MoveLength	clc	adc  #LineSuperItemSize*256	bcc  @1	inx@1	jsr  SetHandleSize	jsr  LockHandle	stax LineBlockStart	clc	adc  MoveLength	sta  LineStartsPtr	txa	adc  MoveLength+2	sta  LineStartsPtr+2	stz  LineStartsCount	;zero out the count field.	ldy  #TERecord.NumberOfLines	jsr  GetRecordLong	clc	adc  #256	bcc  @2	inx@2	ldy  #TERecord.NumberOfLines	jsr  SetRecordLong@done	rts;---------------------------------------------------------------;---------------------------------------------------------------; this subroutine adds the X-Reg to both NewLineLength and TextOffset;---------------------------------------------------------------addXToTextOffset	txa	clc	adc  NewLineLength	sta  NewLineLength	txa	addl TextOffset	rts;---------------------------------------------------------------	ENDPscrollColors	dc.w  $0000		;Outline.	dc.w  $00F0		;Arrow when normal.	dc.w  $00F0		;Arrow when selected.	dc.w  $00F0		;Arrow's box interior.	dc.w  $00F0		;Thumber when normal.	dc.w  $0000		;Not used and should	never be used.	dc.w  $0030		;Page region interior.	dc.w  $00F0		;Interior color of inactive bar.****************************************************************; this routine takes TextOffset pointing anywhere within the current; line and it calculates the width of the LAST field in the line.; It returns TextOffset pointing to the start of the last field, X-Reg; as an offset into the line for the same thing. Finally TempWord is; the field width****************************************************************MeasureLastField	PROCNAME	jsr  FindLineStart		;start at the beginning of the line	jsr  FindTextPtr		;setup the text pointer	ldy  SuperLength		;start at the end of the line	shortm		;short mode for speed@tabLoop	dey		;search backwards for the first TAB	bmi  atStart	lda  [TextPtr],y	cmp  #TAB	bne  @tabLoopatStart	longm		;back to long mode	iny		;skip over the TAB	tya		;move TextOffset to the start of the last	addl TextOffset		;..field	cpy  SuperLength		;are we at the end of the line ?	beq  tabAtEnd	phy		;nope, so save Y-Reg	jsr  MeasureField		;measure the last field	sta  TempWord		;store the result in TempWord	plx		;restore our index into X	rtstabAtEnd	stz  TempWord		;zero out our width	tyx		;X-Reg is our returned index	rts	ENDP********************************************************************************************************************************* This checks TempRect to see if it is contained by the vis region* of the current grafport. carry clr if TempRect IS inside the* region. carry set if not. Uses MemoryPtr.****************************************************************IsTempRectInVisRgn	PROCNAME	ldy  #GrafPort.VisRgn+2	;get the region handle out of the grafport	lda  [GrafPortPtr],y	sta  MemoryPtr+2	ldy  #GrafPort.VisRgn	lda  [GrafPortPtr],y	sta  MemoryPtr	ldy  #2		;deref it into a pointer.	lda  [MemoryPtr],y	tax	lda  [MemoryPtr]	stax MemoryPtr	lda  [MemoryPtr]		;is the vis region rectangular ?	cmp  #10		;if not then we can't check so return	bne  outside		;..FALSE	lda  [MemoryPtr],y	cmp  TempRect.top	bgt  outside	ldy  #4	lda  [MemoryPtr],y	cmp  TempRect.left	bgt  outside	ldy  #6	lda  [MemoryPtr],y	cmp  TempRect.bottom	blt  outside	ldy  #8	lda  [MemoryPtr],y	cmp  TempRect.right	blt  outside	clc		;we are completly within the region !!	rtsoutside	sec	rts	ENDP****************************************************************ScrollUpOne	PROCNAME	jsr  GetScreenTopOffset	lda  TextOffset	ora  TextOffset+2	beq  atTop	decl TextOffset		;get the height of the line right before	jsr  FindLineStart		;..the screen top. start at the line start	jsr  SetScreenTopOffset	;set the new screen top offset	jsr  GetViewRect		;get the view rectangle	lda  LineHeight		;scroll it down by the line height	jsr  VScrollTempRect	jsr  CalculateSelection	jsr  GetScreenTopOffset	jsr  FindLineInfo	jsr  GetViewRect	lda  TempRect.top	clc	adc  LineHeight	sta  TempRect.bottom	ldy  #GrafPort.VisRgn	jsr  GetPortLong	PushAX	jsr  SetupVisRgn		;setup our vis region to clip to the textRect. 	jsr  OffsetToPoint		;find TextVPos for the drawLine	jsr  DrawLine	PullAX	ldy  #GrafPort.VisRgn	jsr  SetPortLong	jsr  SetCtrlValue	clc	rtsatTop	sec	rts	ENDP****************************************************************ScrollDownOne	PROCNAME	jsr  GetScreenTopOffset	;start at the top of the screen for both	ldy  #TERecord.ViewRect.top	;..TextOffset and TextVPos	lda  [RecordPtr],y	sta  TextVPos@loop	jsr  IsTextOffsetAtEnd	beq  atBottom	jsr  FindLineInfo	addl TextOffset,SuperLength,TextOffset	lda  TextVPos	clc	adc  LineHeight	sta  TextVPos	ldy  #TERecord.ViewRect.bottom	cmp  [RecordPtr],y	blt  @loop	jsr  GetScreenTopOffset	;get the height of the line at the screen	jsr  FindLineInfo	addl TextOffset,SuperLength,TextOffset	jsr  SetScreenTopOffset	;set the new screen top offset	jsr  FindLineInfo	jsr  GetViewRect		;get the view rectangle	lda  LineHeight		;scroll it down by the line height	eor  #$FFFF		;change the sign (the INC is part of the	inc  a		;..sign change)	pha	jsr  VScrollTempRect	jsr  CalculateSelection	PullWord LineHeight		;get our saved value into LineHeight	ldy  #GrafPort.VisRgn	jsr  GetPortLong	PushAX	jsr  SetupVisRgn		;setup our vis region to clip to the textRect.	ldy  #TERecord.ViewRect.left	lda  [RecordPtr],y	sta  DrawRect.left	ldy  #TERecord.ViewRect.bottom	jsr  GetRecordLong	sta  DrawRect.bottom	stx  DrawRect.right	clc	adc  LineHeight	sta  DrawRect.top	jsr  DoDraw	PullAX	ldy  #GrafPort.VisRgn	jsr  SetPortLong	jsr  SetCtrlValueatBottom	clc	rts	ENDP****************************************************************SetCtrlValue	PROCNAME	jsr  GetScreenTopOffset	jsr  FindLineInfo	jsr  GetVertScrollBar	beq  skipSet	ldy  LineNumber		;save the new value	dey	phy	PushAX		;the control handle for the scroll bar.	stax TempPtr	jsr  DerefTempPtr	ldy  #CtrlRecord.dataSize	lda  [TempPtr],y	ldy  #CtrlRecord.viewSize	sec	sbc  [TempPtr],y	cmp  5,s	bge  @ok	sta  5,s@ok	_SetCtlValueskipSet	rts	ENDP****************************************************************SetupVisRgn	PROCNAME	jsr  GetViewRect		;clip to the text rectangle	ldy  #GrafPort.VisRgn	;get the region handle, deref it and store	jsr  GetPortLong		;..in memory pointer	jsr  DerefAX	stax MemoryPtr	lda  [MemoryPtr]		;is the region rectangular ? If not, we	cmp  #10		;..must intersect the regions	bne  mustSectRgn	lda  [MemoryPtr],y		;Y-Reg is still two here	cmp  TempRect.top	bgt  notContained	ldy  #4	lda  [MemoryPtr],y	cmp  TempRect.left	bgt  notContained	ldy  #6	lda  [MemoryPtr],y	cmp  TempRect.bottom	blt  notContained	ldy  #8	lda  [MemoryPtr],y	cmp  TempRect.right	bge  setRectClip;---------------------------------------------------------------notContained	ldy  #8		;compare right point	lda  [MemoryPtr],y	cmp  TempRect.right	bpl  @1	sta  TempRect.right@1	ldy  #6		;compare bottom point	lda  [MemoryPtr],y	cmp  TempRect.bottom	bpl  @2	sta  TempRect.bottom@2	ldy  #4		;compare l