******************************************************; this routine returns the screen point TextVPos and TextHPos; associated with TextOffset. It returns carry set (TRUE) if the; offset is not on the screen. In this case TextVPos and TextHPos; will be the topleft of the viewRect or the botRight of the viewRect****************************************************************OffsetToPoint	PROCNAME	movl TextOffset,OriginalOffset	;save this for comparing against later	ldy  #TERecord.ViewRect.top	;start TextVPos at the top of the	lda  [RecordPtr],y		;..viewRect	sec	ldy  #TERecord.TopTextVPos	sbc  [RecordPtr],y	sta  TextVPos	ldy  #TERecord.TopTextOffset	;start scanning from the top of the screen	jsr  GetRecordLong	cpx  TextOffset+2		;check to see if the offset we are looking	blt  pastTheTop		;..for is before the top of the screen.	bne  abortTop		;If so, then abort with carry set and	cmp  TextOffset		;..TextVPos set to the viewRect.top	ble  pastTheTop		;we're on screen here so continue;---------------------------------------------------------------abortTop	ldy  #TERecord.ViewRect.top	;start TextVPos at the top of the	lda  [RecordPtr],y		;..viewRect	sta  TextVPos	jsr  GetLeftMargin		;find the leftmost position in the line	sta  TextHPos		;..and return this as the TextHPos when	jsr  GetLeftEdge		;..aborting because of being before the	cmp  TextHPos		;..screen top	bge  abortBottom	sta  TextHPosabortBottom	ldy  #TERecord.ViewRect.left	lda  TextHPos	clc	adc  [RecordPtr],y	sta  TextHPos	movl OriginalOffset,TextOffset	;restore the original text offset	sec		;set the carry to indicate the text is	rts		;..off the screen. Then return;---------------------------------------------------------------pastTheTop	stax TextOffset		;start at the offset of the screen top.@lineLoop	jsr  FindLineInfo		;find the line length and height	lda  TextOffset		;add the length to TextOffset and leave	clc		;..the result in the X-Reg (low) and the	adc  SuperLen