		;set ours from our WAP	beq  notStarted		;if zero, then we are not started	stx  TempWord		;use TempWord to hold the return address	tyx		;check to see if the number of parameters	beq  @skipMove		;..is zero.	clc		;make a pointer to our parameter	adc  #ParameterSpace-2	;..area in our direct page and save it	pea  $0000		;the high word is zero	pha	tsc		;get the current stack pointer	phx		;save the number of parameters for adjust	phd		;save our direct page	phx		;save the number of parameters for move	tcd		;set direct page to the old stack pointer@loop	lda  UserStuff-2,x		;copy our parameters to OUR direct page	txy	sta  [TEDirectPtr],y	dex	dex	bne  @loop@stripIt	plx		;get back the number of parameters	lda  RPart3		;copy the user's direct page and the two	sta  RPart3,x		;..return addrs over the parameters	lda  RPart2	sta  RPart2,x	lda  RPart1	sta  RPart1,x	lda  UserDirectPage		sta  UserDirectPage,x	tdc		;get the original stack pointer	pld		;restore our direct page	clc		;adjust the stack pointer by	adc  1,s		;..the number of parameters	adc  #4		;skip over the allocated pointer	tcs		;and set it back.@skipMove	phb		;save the user's data bank	phk		;set our data bank.	plb	pei  TempWord	rts		;return to callernotStarted	tsc	tcd	lda  RPart3-4		;copy the user's direct page and the two	sta  RPart3-4,x		;..return addrs over the parameters	lda  RPart2-4	sta  RPart2-4,x	lda  RPart1-4	sta  RPart1-4,x	lda  UserDirectPage-4	sta  UserDirectPage-4,x	phx	tdc		;adjust the stack	clc	adc  1,s	tcs	phb		;save the user's data bank	phk		;set our data bank.	plb	ldx  #teNotStarted		;load the not started error;---------------------------------------------------------------QuickExit	plb		;restore the original data bank	pld		;restore original direct page	txa		;put the error code into A	cmp  #1		;set the carry flag	jml  DecBusyFlg		;decrement busy flag and return to caller;---------------------------------------------------------------StandardEntry	plx		;pull off the return address	phd		;save the user's direct page	tcd		;set ours from our WAP	beq  notStarted		;if zero, then we are not started, so use	stx  RetSave		;..quick entry to exit.	pld	jsr  QuickEntry		;setup TextEdit. number of parameters in Y	lda  RecordHandle	ora  RecordHandle+2	bne  useThisOne	PushLongSpace	_FindActiveCtl	tax		;put the error code in the X-Reg	pla	sta  RecordHandle	pla	sta  RecordHandle+2	bcs  QuickExituseThisOne	jsr  LockRecordHandle	;lock the main record handle	PushLongSpace		;save the current port	_GetPort	jsr  SetWindowPort	pei  RetSave	rts;---------------------------------------------------------------StandardExit	stx  ErrorCode	_SetPort	jsr  UnlockRecordHandle	ldx  ErrorCode	bra  QuickExit;---------------------------------------------------------------	ENDP****************************************************************	DSECT WorkAreadstPortPtr	long		;these are for the low level drawingsrcPtr	long		;..routinesdstPtr	longsrcWidth	worddstWidth	wordnumberOfWords	wordnumberOfLines	wordleftMask	wordrightMask	word****************************************************************FindWordEnd	PROCNAME bra  FindWordEndNew	decl TextOffset	jsr  FindTextPtr	lda  [TextPtr]	jsr  IsItAWordBreak	bcs  alreadyThere@loop	incl TextOffset	jsr  IsOffsetAtEnd	beq  atEnd	jsr  FindTextPtr	lda  [TextPtr]	jsr  IsItAWordBreak	bcc  @loopatEnd	rtsalreadyThere	incl TextOffset	rts	ENDP***************************************************************** the value to be draw comes in in A****************************************************************DebugHexWord	PROC  EXPORT	phb		;save the data bank	phk		;set it to ours	plb	PushLongSpace	pha	_HexIt	PullLong tempStr	PushLong #theRect	_GetPen	PushLong #theInfo	_GetFontInfo	PushWordSpace	PushLong #tempStr	_CStringWidth	pla	clc	adc  theRectLeft	sta  theRectRight	lda  theRectTop	clc	adc  theInfoAscent	ad