TextBlock.textLength+2	;..to search through	lda  [TempPtr],y	bne  @1	dey	dey	lda  [TempPtr],y	cmp  #$FFE0	bge  @1	tax@1	ldy  #TextBlock.textStart+SplitBlockSize	shortm		;look for the first carriage return after@loop	lda  [TempPtr],y		;..the splitting block size. Note that	cmp  #CR		;..if we can't find a CR in the first	beq  doIt		;..64K, we abort the split	iny	dex	bne  @loop	longmabortIt	rts;---------------------------------------------------------------doIt	longm		;back to long mode	cpy  #$FEFF		;If our index is greater than this, we	bge  abortIt		;..will break some other code later on	tya		;..that assumes no overflow from a word.	sec		;If our index is too big, then abort the	sbc  #TextBlock.textStart	;..split. Otherwise adjust the index back	sta  TempWord		;..to a text offset and this is the new	ldy  #TextBlock.textLength	;..length of the old block. Now find the	lda  [TempPtr],y		;..length of the NEW block.	sec	sbc  TempWord	sta  MoveLength	lda  TempWord		;also set the new length of the old block	sta  [TempPtr],y		;..in the record.	iny	iny	lda  [TempPtr],y	sbc  #0	sta  MoveLength+2	lda  #0		;the high word of the new length is always	sta  [TempPtr],y		;..zero	ldax MoveLength		;round off and adjust the new length. Then	and  #$FF00		;..get a handle of the proper size	clc	adc  #256+TextBlock.textStart	bcc  @1	inx@1	jsr  GetLargeHandle		;if we get a memory error, then abort the	bcs  abortIt		;..split	stax TempLong		;save the new handle in TempLong and	jsr  DerefAX		;..deref it into MemoryPtr	stax MemoryPtr	jsr  BlockHandleToPtr	;reset TempPtr in case the block moved	ldy  #TextBlock.nextHandle	;set the next handle field for both the	lda  [TempPtr],y		;..new block and the old block	sta  [MemoryPtr],y	lda  TempLong	sta  [TempPtr],y	iny	iny	lda  [TempPtr],y	sta  [MemoryPtr],y	lda  TempLong+2	sta  [TempPtr],y	ldy  #TextBlock.prevHandle	;set the previous handle of the new block	lda  BlockHandle	sta  [MemoryPtr],y	iny	iny	lda  BlockHandle+2	sta  [MemoryPtr],y	ldy  #TextBlock.textLength	;set the length of the new block	lda  MoveLength	sta  [MemoryPtr],y	iny	iny	lda  MoveLength+2	sta  [MemoryPtr],y	ldy  #TextBlock.flags	;clear the flags for the new block	lda  #0	sta  [MemoryPtr],y	lda  TempWord		;find the source pointer for moving the	clc		;..text from the old block to the new one	adc  #TextBlock.textStart	adc  TempPtr	sta  SourcePtr	lda  TempPtr+2	adc  #0	sta  SourcePtr+2	lda  #TextBlock.textStart	;the dest pointer is the pointer to the	clc		;..start of the new block adjusted for	adc  MemoryPtr		;..the header	sta  DestPtr	lda  MemoryPtr+2	adc  #0	sta  DestPtr+2	jsr  BlockMove		;move the text	PushZLong BlockHandle	;set the size of the old handle to free	ldx  #0		;..up memory	lda  TempWord	and  #$FF00	clc	adc  #256+TextBlock.textStart	jsr  SetHandleSize	jsr  BlockHandleToPtr	;reset TempPtr in case the block moved	jsr  MoveToNextBlock	;this moves to the newly created block	jsr  MoveToNextBlock	;find the next block and if there is one	bcs  @allDone		;..then set the prev handle field of it	ldy  #TextBlock.prevHandle	;..to the new block	lda  TempLong	sta  [TempPtr],y	iny	iny	lda  TempLong+2	sta  [TempPtr],y@allDone	rts;---------------------------------------------------------------	ENDP***************************************************************** this routine concatenates two handles****************************************************************HandAndHand	PROCNAME  Export;---------------------------------------------------------------	DefineStackorigD	wordreturnAddr	wordsrcHandle	longdstHandle	long;---------------------------------------------------------------	phd		;save the old direct page	tsc		;setup our new direct page	tcd	ldy  #HandleRecord.length	;get the size of the destination handle	lda  [dstHandle],y	pha		;save the low word of the old length	clc	adc  [srcHandle],y	tax	iny	iny	lda  [dstHandle],y	pha		;save the high word of the old length	adc  [srcHandle],y	pha		;Push the new size for set handle size	phx	PushZLong dstHandle	_SetHandleSize	bcs  error	lda  [dstHandle],y		;add the size of the original dest	tax		;..handle and put it in dest handle	pla	clc	adc  [dstHandle]	sta  dstHandle	txa	adc  1,s	sta  dstHandle+2	plx	ldy  #2	lda  [srcHandle],y	tax	lda  [srcHandle]	PushAX	PushZLong dstHandle		;now a pointer to the end of the old dest	ldy  #HandleRecord.length+2	;get the size of the source handle	lda  [srcHandle],y	pha	dey	dey	lda  [srcHandle],y	pha	PushWord #%0000100000000101	jsl  $E10200		;use the memory mover	lda  returnAddr	sta  dstHandle+2	clc		;indicate no error;---------------------------------------------------------------done	pld	pla		;pull off 8 bytes of garbage	pla	pla	pla	rts	;---------------------------------------------------------------error	tax	pla		;cleanup the stack	pla	sec	bra  done;---------------------------------------------------------------	ENDP****************************************************************Save0_4	PROCNAME  Export	ply	pei  2	pei  0	phy	rts	ENDP****************************************************************Restore0_4	PROCNAME  Export	pha	lda  5,s	sta  2	pla	sta  3,s	pla	sta  0	pla	rts	ENDP****************************************************************IncRecordLong	PROCNAME  Export	lda  [RecordPtr],y	inc  a	sta  [RecordPtr],y	bcc  skipHigh	iny	iny	lda  [RecordPtr],y	inc  a	sta  [RecordPtr],yskipHigh	rts	ENDPmoveGrowBox	PushLongSpace		;find the new top/left of the grow box	_GrowSize		;..and move it to this position	ldy  #GrafPort.portRect.bottom	lda  [TempPtr],y	inc  a	sec	sbc  1,s		;leave the new Y-Pos on the stack	sta  1,s	ldy  #GrafPort.portRect.right	lda  [TempPtr],y	inc  a	sec	sbc  3,s		;leave the new X-Pos on the stack	sta  3,s	jsr  GetGrowBoxHandle	;push the control handle	Pus