k	stax iTheTemp	; save it for later in the temp	ldax BlockStart	; see if we are at the beginning of a block..	cmp  TextOffset	; by comparing to the text offset	bne  @NotAtStart	cpx  TextOffset+2	beq  @AtStart@NotAtStart	subl TextOffset,BlockStart,iTheTemp	; temp:=offset-blkStart	subl BlockLength,iTheTemp,iTheTemp	; temp:=Length-temp@AtStart	ldax iTheTemp	; temp now contains the size of the rest of the block	PushAX	; save the current block length...	ldax TextPtr	; push the BlockPointer	pushAX	ldax xRecordHandle	; and finally the record handle..	pushAX	jsl CallCallBack	; now call the callback routine!		jsr  BlockHandleToPtr	; re-deref the current super handle	ldy  #TextBlock.nextHandle+1	; see if this was the last block	lda  [tempPtr],y	beq  @AtTheEnd		; if we are at the last block then just get out!; bump textoffset and continue	addl TextOffset,iTheTemp,TextOffset	; offset := offset+temp	subl iTheLength,iTheTemp,iTheLength	; length:=length-temp	lda  iTheLength+2	bmi  @AtTheEnd		; if negative, then we are done..	ora  iTheLength	beq  @AtTheEnd		; or if its zero we are done!	bra  @loop;---------------------------------------------------------------@AtTheEnd	ldx  #0;---------------------------------------------------------------allDone			;if the buffer was full, return buffer	cpx  #1		;..full error	rts;---------------------------------------------------------------CallCallBack; This routine calls the routine passed by the programmer by cleverly; stuffing its address-1 on the stack and RTLing	pha		; make room on the stack for 3 bytes..	phk	lda  CallBackPtr+1	sta  2,s	lda  CallBackPtr	dec  a	sta  1,s	rtl	;---------------------------------------------------------------doWholeRecord; Set up the start to 0 and the length to the number of chars in the record	stzL TextOffset		; set the start to 0	jsr  GetTextLength	stx  iTheLength+2	sta  iTheLengthdoTestLength	ora  iTheLength+2		; be sure we have data to run!	bne  @ok	se