dOffset	sec	rts;---------------------------------------------------------------WalkTbl	dc.w  doWholeRecord	dc.w  doFromSelStart	dc.w  doFromSelEnd	dc.w  doSelectionOnly	dc.w  doFromArbitrary	dc.W  doGivenRange;---------------------------------------------------------------	ENDP****************************************************************